set -eu
systemctl stop cleanup-github.service
runuser -l root -c 'cd /opt/cleanup/repo && git fetch origin aws-github-finals && git checkout --detach FETCH_HEAD && /usr/local/go/bin/go build -p 2 -o .build/githubci ./cmd/githubci && bash scripts/finalizer-build.sh && python3 scripts/finalizer-config.py && cp .build/api-config.json .build/api-config.previous.json && python3 -c "import json,pathlib; p=pathlib.Path(\".build/api-config.json\"); c=json.loads(p.read_text()); c[\"policy\"]=json.loads(pathlib.Path(\".build/finalizer-config.json\").read_text())[\"policy\"]; p.write_text(json.dumps(c))" && API_IMAGE=$(cat .build/api-image-id) docker compose -f compose.api.yaml up -d --force-recreate api gateway && python3 scripts/aws/install-services.py' > /opt/cleanup/update.log 2>&1
